declare
 payload jsonb := $payload${"updates":[{"entry_id":"606582f3-942c-5755-9898-ce97e671154d","expected_revision_id":"7d92ff56-81bd-4827-b766-01c9a64b22ba","path":"/","content":{"seo":{"title":"Asesoría jurídica para decidir con claridad","noindex":false,"description":"ALBAR Abogados: orientación y representación para personas y empresas, con una estrategia construida a partir de los hechos de cada caso."},"path":"/","terms":[],"title":"Asesoría jurídica para decidir con claridad","blocks":[{"key":"5f453805-7bb7-54a4-98f4-e2f480e3d6b8","data":{"body":"¿Enfrentas un sobreendeudamiento, una separación, un asunto de alimentos u otro problema legal y no sabes por dónde empezar? En Albar revisamos tu situación, te explicamos tus opciones y definimos contigo los próximos pasos a partir de los antecedentes de tu caso, con un trato cercano y honesto.","actions":[{"href":"/contacto","label":"Solicitar evaluación de mi caso"}],"eyebrow":"ALBAR Abogados · Personas y empresas","heading":"Cuando una decisión cambia tu vida, necesitas una estrategia diseñada a tu medida."},"type":"hero","assets":[{"slot":"image","alt_text":"Claudia Albiña Aros de pie junto al ventanal de su oficina.","asset_id":"c1ad540b-01f8-4303-b8f9-6fa55534d0bf","focal_point":{"x":0.54,"y":0.34}}],"variant":"image-right","schema_version":1},{"key":"d3e937a2-e8f3-57c5-b386-c0f14fd18af8","data":{"items":[{"body":"Comprende qué alternativas pueden corresponderte y qué efectos tendrían sobre tus bienes y obligaciones.","href":"/personas/insolvencia-y-reemprendimiento","heading":"Mis deudas superan mi capacidad de pago","link_label":"Conocer mis opciones"},{"body":"Revisa cómo solicitar, modificar o exigir el cumplimiento de los alimentos según tu situación.","href":"/personas/derecho-de-familia/pension-de-alimentos","heading":"Necesito asegurar o ajustar la pensión de mis hijos","link_label":"Conocer mis opciones"},{"body":"Conoce las alternativas de divorcio y las decisiones familiares y patrimoniales que conviene anticipar.","href":"/personas/derecho-de-familia/divorcios","heading":"Quiero ordenar mi separación","link_label":"Conocer mis opciones"},{"body":"Evalúa la situación del negocio y las alternativas concursales antes de comprometer otra decisión.","href":"/empresas/insolvencia-y-reemprendimiento","heading":"Necesito decidir el futuro de mi empresa","link_label":"Conocer mis opciones"}],"eyebrow":"Empieza por lo que necesitas lograr","heading":"¿Qué necesitas resolver hoy?"},"type":"card_grid","assets":[],"variant":"default","schema_version":1},{"key":"9ea16a41-3b1f-56ac-a402-b0209d0d7b7a","data":{"body":"Somos ALBAR Abogados. Asesoramos y representamos a personas y empresas con una estrategia construida a partir de los hechos de cada caso. Nuestra fundadora, Claudia Albiña Aros, combina el análisis de los antecedentes con una explicación clara de las alternativas. Trabajamos para que comprendas tus opciones y puedas decidir cómo avanzar.","eyebrow":"Conoce a ALBAR","heading":"Una estrategia empieza por escuchar tu realidad."},"type":"split_content","assets":[{"slot":"image","alt_text":"Claudia Albiña Aros sentada frente a su escritorio.","asset_id":"e8363b8e-195b-48e8-8826-1b653e9672f8","focal_point":{"x":0.52,"y":0.46}}],"variant":"default","schema_version":1},{"key":"f6bc2941-e159-59f5-85fe-23dcdcf772c1","data":{"items":[{"body":"Revisamos tus prioridades, los antecedentes disponibles y aquello que necesitas resolver.","heading":"Tu situación, antes que una fórmula"},{"body":"Conocerás las alternativas, sus requisitos, riesgos y preguntas pendientes antes de decidir.","heading":"Una explicación comprensible"},{"body":"La recomendación se construye a partir de los hechos y documentos de tu caso.","heading":"Una estrategia fundada"},{"body":"Las gestiones que se propongan y sus condiciones se acuerdan antes de asumir el encargo.","heading":"Alcance y honorarios claros"}],"eyebrow":"Una estrategia para tu situación","heading":"Lo que puedes esperar del acompañamiento de ALBAR"},"type":"card_grid","assets":[],"variant":"default","schema_version":1},{"key":"1f92fa84-6ff2-5dba-bf4e-8d773f9a0563","data":{"source":"posts","eyebrow":"Información para empezar","heading":"Lecturas que ayudan a ordenar tus preguntas"},"type":"related_content","assets":[],"variant":"default","schema_version":1},{"key":"02e83f3e-d03c-4d7c-861e-a01c93ab77bf","type":"testimonials","schema_version":1,"variant":"default","data":{"eyebrow":"Testimonios","heading":"Experiencias con ALBAR"},"assets":[]},{"key":"6ee1571b-b83d-5ee6-9f94-8e3cd47c1c92","data":{"body":"Basta una descripción general de lo que ocurre. El siguiente paso es conocer el contexto y acordar cómo evaluar tu caso.","actions":[{"href":"/contacto","label":"Solicitar evaluación de mi caso"}],"eyebrow":"El primer paso es conocer tus opciones","heading":"No necesitas tener todas las respuestas para consultar."},"type":"cta","assets":[],"variant":"default","schema_version":1}],"authors":["d4d402d3-0f0b-5a3c-bf0c-93a5ee3ccfb1"],"excerpt":"ALBAR Abogados: orientación y representación para personas y empresas, con una estrategia construida a partir de los hechos de cada caso.","relations":[],"template_key":"home","cover_asset_id":"c1ad540b-01f8-4303-b8f9-6fa55534d0bf","template_version":1}},{"entry_id":"cea7ff50-d0ff-5c5c-abb3-05c7f2b529de","expected_revision_id":"cd9cfc35-f9ae-4096-91ba-9bcb5368147c","path":"/sobre-albar","content":{"seo":{"title":"Conoce a ALBAR Abogados y Claudia","noindex":false,"description":"Somos ALBAR Abogados: asesoramos y representamos a personas y empresas con una estrategia fundada en los hechos, un trato cercano y claridad para decidir."},"path":"/sobre-albar","terms":[],"title":"Conoce a ALBAR Abogados y Claudia","blocks":[{"key":"cb1c1621-1d2d-42f1-8eed-16b1fcba8dd4","data":{"body":"Somos un estudio jurídico que nace de una convicción: cada persona y cada empresa merecen una estrategia diseñada para su realidad. Detrás de una consulta hay decisiones que pueden cambiar una vida, una familia o el futuro de un negocio. Por eso, nuestro trabajo comienza por escuchar y comprender el contexto de cada caso.\n\nEn ALBAR basamos nuestras recomendaciones en los hechos y en los antecedentes disponibles. Explicamos las alternativas con honestidad y acordamos los próximos pasos con un trato cercano, tanto en la asesoría preventiva como en la representación judicial.\n\nNuestro nombre surge del de nuestra fundadora, Claudia Albiña Aros. Expresa una forma de ejercer el Derecho en la que la confianza, el estudio riguroso y el acompañamiento forman parte de cada asesoría.","eyebrow":"Nuestro estudio","heading":"El origen de ALBAR Abogados"},"type":"split_content","assets":[],"variant":"default","schema_version":1},{"key":"fee12b6f-40da-5687-8a2d-7bf3412e5c61","data":{"body":"ALBAR fue fundado por Claudia Albiña Aros, abogada formada en la Pontificia Universidad Católica de Chile. Su trayectoria incluye experiencia en estudios jurídicos y en materias del sector público y privado, una práctica profesional en la Fiscalía Metropolitana Sur y participación, a través de un estudio externo, en asesoría laboral para una empresa del sector retail.\n\nCon esa experiencia como base, en ALBAR asesoramos y representamos a personas y empresas en asuntos de familia, laborales, civiles, de insolvencia, corporativos y de contratación pública. Combinamos la revisión de antecedentes con una planificación jurídica ajustada a las necesidades de cada cliente.","eyebrow":"Nuestra fundadora","heading":"Conoce a Claudia Albiña Aros"},"type":"split_content","assets":[{"slot":"image","alt_text":"Claudia Albiña Aros sentada frente a su escritorio.","asset_id":"e8363b8e-195b-48e8-8826-1b653e9672f8","focal_point":{"x":0.52,"y":0.46}}],"variant":"image-left","schema_version":1},{"key":"1245fa74-ed0d-4821-b07f-b5c9f7e0fda6","data":{"tone":"primary","items":[{"body":"Clientes asesorados y representados por nuestra fundadora durante su trayectoria.","icon":"users","heading":"+100"},{"body":"Asesoría jurídica integral y estrategias adaptadas a cada realidad.","icon":"heart-handshake","heading":"Personas y empresas"},{"body":"Acompañamiento preventivo y representación en controversias.","icon":"scale","heading":"Litigación y asesoría jurídica"},{"body":"Formación de nuestra fundadora y compromiso con la actualización profesional.","icon":"book-open-check","heading":"Abogada PUC"}],"columns":"4","aria_label":"Experiencia y enfoque de ALBAR"},"type":"card_grid","assets":[],"variant":"metrics","schema_version":1},{"key":"01f32563-8d22-42fc-b5b8-f4aa1f96e417","data":{"body":"La formación de nuestra fundadora y el estudio permanente respaldan nuestra forma de abordar cada caso.","items":[{"body":"Pontificia Universidad Católica de Chile","icon":"book-open-check","detail":"Título profesional obtenido en 2023.","heading":"Abogada"},{"body":"Pontificia Universidad Católica de Chile","icon":"file-check","detail":"Major en Derecho. Minor en Relaciones Internacionales.","heading":"Licenciada en Ciencias Sociales"},{"body":"Pontificia Universidad Católica de Chile","icon":"scale","detail":"2025.","heading":"Diplomado en Derecho Penal Económico"},{"body":"Actualización jurídica permanente","icon":"file-text","detail":"Participamos en diplomados, seminarios y programas de actualización en distintas áreas del Derecho.","heading":"Formación continua"}],"columns":"4","eyebrow":"La preparación detrás de cada estrategia","heading":"Formación y actualización profesional"},"type":"card_grid","assets":[],"variant":"credentials","schema_version":1},{"key":"cde05f55-c6fa-4241-b69d-9f0dec1dbe7a","data":{"items":[{"body":"Comprendemos el contexto y las prioridades de cada cliente antes de proponer una vía.","icon":"message-circle","heading":"Escuchamos antes de recomendar"},{"body":"Distinguimos los hechos acreditados, la información pendiente y las decisiones que dependen de ella.","icon":"book-open-check","heading":"Trabajamos con antecedentes"},{"body":"Presentamos las alternativas, sus condiciones y sus posibles efectos para que puedas decidir con información.","icon":"heart-handshake","heading":"Explicamos con claridad"},{"body":"Definimos el alcance del encargo, las actuaciones y los honorarios antes de iniciar las gestiones.","icon":"wallet-cards","heading":"Acordamos cómo avanzar"}],"columns":"4","eyebrow":"Nuestra forma de trabajar","heading":"Una estrategia empieza por escuchar"},"type":"card_grid","assets":[],"variant":"default","schema_version":1},{"key":"c9bfade2-1793-4b4b-920a-2260498dadca","data":{"body":"Asesoramos y representamos en distintas materias. El primer paso es revisar la situación y determinar qué vía corresponde.","items":[{"body":"Asesoramos en divorcios, alimentos, cuidado personal, relación directa y regular, compensación económica y medidas de protección.","href":"/personas/derecho-de-familia","icon":"users","heading":"Derecho de familia","link_label":"Conocer el área"},{"body":"Asesoramos y representamos ante despidos, conflictos laborales, vulneraciones de derechos y accidentes del trabajo.","href":"/personas/derecho-laboral","icon":"wallet-cards","heading":"Derecho laboral","link_label":"Conocer el área"},{"body":"Revisamos contratos, arrendamientos, responsabilidad civil y cumplimiento de obligaciones, y representamos en litigios.","href":"/personas/derecho-civil","icon":"file-text","heading":"Derecho civil","link_label":"Conocer el área"},{"body":"Evaluamos alternativas de reorganización o liquidación para personas y empresas según sus antecedentes y los requisitos aplicables.","href":"/liquidacion-concursal","icon":"coins","heading":"Insolvencia y reemprendimiento","link_label":"Conocer el área"}],"columns":"4","eyebrow":"Cómo podemos ayudarte","heading":"Áreas de práctica"},"type":"card_grid","assets":[],"variant":"practice","schema_version":1},{"key":"528bd342-582e-4cc6-8a59-0d407ab3dfe8","type":"testimonials","schema_version":1,"variant":"default","data":{"eyebrow":"Testimonios","heading":"Experiencias con ALBAR"},"assets":[]},{"key":"c39e65fd-3f70-4628-8f09-04cbfb16c712","data":{"body":"En ALBAR revisamos los antecedentes, explicamos las alternativas y definimos contigo los próximos pasos. Cuéntanos qué necesitas resolver para comenzar.","actions":[{"href":"/contacto","icon":"arrow-up-right","label":"Solicitar evaluación de mi caso","style":"primary"}],"eyebrow":"Conversemos sobre tu situación","heading":"Cada caso merece una estrategia diseñada para su realidad."},"type":"cta","assets":[],"variant":"default","schema_version":1}],"authors":["d4d402d3-0f0b-5a3c-bf0c-93a5ee3ccfb1"],"excerpt":"Somos ALBAR Abogados: asesoramos y representamos a personas y empresas con una estrategia fundada en los hechos, un trato cercano y claridad para decidir.","relations":[],"template_key":"default","cover_asset_id":null,"template_version":1}},{"entry_id":"0431db74-5d6f-5f58-b9f5-4bc30de43baf","expected_revision_id":"84c2dd7c-bfa0-454f-b737-da43f3a6b3e0","path":"/personas","content":{"seo":{"title":"Soluciones legales para personas","noindex":false,"description":"Encuentra una orientación según la situación que necesitas resolver."},"path":"/personas","terms":[],"title":"Soluciones legales para personas","blocks":[{"key":"c2651ac0-d7a5-55e8-9055-7d7ba023d292","data":{"body":"Empieza por el cambio que necesitas lograr. Revisaremos tu situación familiar o financiera y las alternativas que podrían corresponderte.","actions":[{"href":"/contacto","label":"Solicitar evaluación de mi caso"}],"eyebrow":"Personas","heading":"Una situación difícil se enfrenta mejor con un camino claro."},"type":"hero","assets":[{"slot":"image","alt_text":"Claudia Albiña Aros trabajando con un computador portátil en su escritorio.","asset_id":"802739b1-6cf9-4f44-ba65-aaf00f9310cf","focal_point":{"x":0.52,"y":0.44}}],"variant":"image-right","schema_version":1},{"key":"9ed21d2f-f710-5829-8993-7f148fe62ff1","data":{"items":[{"body":"Evalúa tu situación antes de iniciar un procedimiento concursal.","href":"/personas/insolvencia-y-reemprendimiento","heading":"No puedo seguir pagando mis deudas","link_label":"Conocer mis opciones"},{"body":"Identifica qué alternativa de divorcio puede ajustarse a tus antecedentes.","href":"/personas/derecho-de-familia/divorcios","heading":"Quiero poner término a mi matrimonio","link_label":"Conocer mis opciones"},{"body":"Ordena las necesidades, los aportes y los cambios que conviene acreditar.","href":"/personas/derecho-de-familia/pension-de-alimentos","heading":"Necesito regular o modificar los alimentos","link_label":"Conocer mis opciones"},{"body":"Conoce las vías para solicitar el cumplimiento de una pensión fijada.","href":"/personas/derecho-de-familia/pension-de-alimentos/cobro","heading":"La pensión no se está pagando","link_label":"Conocer mis opciones"}],"eyebrow":"Una estrategia para tu situación","heading":"¿Cuál es tu situación?"},"type":"card_grid","assets":[],"variant":"default","schema_version":1},{"key":"69fdd89e-9d83-509b-b334-129c2e96021c","data":{"items":[{"heading":"Conocemos tu caso","body":"Escuchamos tu situación y reunimos los antecedentes para entender tu caso."},{"heading":"Diseñamos la estrategia","body":"Analizamos las alternativas legales y diseñamos una estrategia ajustada a tu situación."},{"heading":"Te acompañamos","body":"Te representamos y asesoramos durante el proceso, con una comunicación cercana y constante."},{"heading":"Buscamos la mejor solución posible","body":"Trabajamos para proteger tus intereses y buscar la solución más favorable que permitan los antecedentes de tu caso."}],"heading":"¿Cómo trabajamos?"},"type":"steps","assets":[],"variant":"default","schema_version":1},{"key":"7b0b0f3a-77ff-5adf-93e7-8114dd49214e","data":{"body":"Cuéntanos de forma general qué ocurre y qué necesitas resolver.","actions":[{"href":"/contacto","label":"Solicitar evaluación de mi caso"}],"eyebrow":"El primer paso es conocer tus opciones","heading":"Empecemos por tu principal preocupación."},"type":"cta","assets":[],"variant":"default","schema_version":1},{"key":"91f29431-db52-591f-85a3-61abf428eb55","data":{"items":[{"body":"Si consideras que tus derechos como trabajador fueron vulnerados, recibirás asesoría para evaluar tu situación y ejercer las acciones legales que correspondan. Te representamos frente a despidos, incumplimientos del empleador, vulneraciones de derechos fundamentales, accidentes laborales y otras situaciones que puedan afectar tus derechos en el trabajo.","href":"/personas/derecho-laboral","heading":"Derecho laboral","link_label":"Conocer el servicio"},{"body":"Muchas situaciones de la vida cotidiana pueden tener consecuencias jurídicas importantes. Recibir asesoría a tiempo permite proteger tus derechos, evitar conflictos futuros y tomar decisiones con mayor seguridad.","href":"/personas/derecho-civil","heading":"Derecho civil","link_label":"Conocer el servicio"},{"body":"Algunos de los actos jurídicos más importantes de tu vida requieren documentos correctamente redactados y formalizados. Te asesoramos en la preparación y revisión de escrituras e instrumentos jurídicos, procurando que cada acuerdo resguarde adecuadamente tus intereses y te entregue la seguridad jurídica que necesitas.","href":"/personas/escrituras-publicas","heading":"Escrituras públicas","link_label":"Conocer el servicio"}],"heading":"Más áreas en las que podemos ayudarte"},"type":"card_grid","assets":[],"variant":"default","schema_version":1}],"authors":["d4d402d3-0f0b-5a3c-bf0c-93a5ee3ccfb1"],"excerpt":"Encuentra una orientación según la situación que necesitas resolver.","relations":[],"template_key":"default","cover_asset_id":"802739b1-6cf9-4f44-ba65-aaf00f9310cf","template_version":1}},{"entry_id":"8b130478-5b90-5eb6-85b3-897d906317cc","expected_revision_id":"3c87ef80-26dc-44e4-a9a5-7128ce926c70","path":"/empresas","content":{"seo":{"title":"Orientación jurídica para decisiones de empresa","noindex":false,"description":"Evalúa la situación financiera de tu empresa y los pasos que conviene analizar antes de actuar."},"path":"/empresas","terms":[],"title":"Orientación jurídica para decisiones de empresa","blocks":[{"key":"0bbe4883-92a0-5609-9f06-be6e4aafd0bf","data":{"body":"Cuando las obligaciones comprometen la continuidad de la empresa, una evaluación de sus antecedentes permite distinguir entre dificultades transitorias y una situación que requiere una salida concursal.","actions":[{"href":"/contacto","label":"Solicitar evaluación de mi caso"}],"eyebrow":"Empresas","heading":"Antes de decidir el futuro del negocio, entiende tus alternativas."},"type":"hero","assets":[{"slot":"image","alt_text":"Claudia Albiña Aros trabajando con un computador portátil en su escritorio.","asset_id":"a8d56727-b8a4-4ea6-b7c5-345b6a0b7d5a","focal_point":{"x":0.55,"y":0.43}}],"variant":"image-right","schema_version":1},{"key":"4578e100-20a8-5572-b3fc-f2278aeaf108","data":{"items":[{"body":"Revisa deudas, activos, operación y procesos pendientes.","href":"/empresas/insolvencia-y-reemprendimiento","heading":"Evaluar la insolvencia del negocio","link_label":"Conocer mis opciones"},{"body":"Distingue entre persona y empresa deudora y entre las vías que podrían ser aplicables.","href":"/liquidacion-concursal","heading":"Comprender qué procedimiento corresponde","link_label":"Conocer mis opciones"}],"eyebrow":"Una estrategia para tu situación","heading":"Ordena la decisión que necesitas tomar"},"type":"card_grid","assets":[],"variant":"default","schema_version":1},{"key":"491fe0b1-a37d-5c82-b01d-b4dcc3cca07f","data":{"items":[{"text":"Actividad de la empresa y situación tributaria."},{"text":"Relación de obligaciones, acreedores y vencimientos."},{"text":"Activos, garantías y flujo de ingresos."},{"text":"Juicios, cobranzas y obligaciones laborales, cuando existan."}],"heading":"Antecedentes para una evaluación inicial","hidden":true},"type":"checklist","assets":[],"variant":"default","schema_version":1},{"key":"283833ba-c9d8-5ecf-a4d0-6857990f73df","data":{"items":[{"body":"Identificamos qué necesitas resolver y revisamos los antecedentes relevantes.","heading":"Ordenamos el caso"},{"body":"Te explicamos las vías disponibles, sus condiciones y los puntos que requieren prueba.","heading":"Definimos las alternativas"},{"body":"Si decides avanzar, delimitamos las actuaciones y los honorarios antes de iniciar gestiones.","heading":"Acordamos el encargo"},{"body":"Realizamos las gestiones acordadas y te informamos sobre los hitos que correspondan.","heading":"Te acompañamos"}],"heading":"Así podemos acompañarte"},"type":"steps","assets":[],"variant":"default","schema_version":1},{"key":"36007b76-c935-5300-828f-3376b54dfe47","data":{"body":"Revisemos los antecedentes del negocio antes de elegir una vía.","actions":[{"href":"/contacto","label":"Solicitar evaluación de mi caso"}],"eyebrow":"El primer paso es conocer tus opciones","heading":"Decide con una visión completa de la situación."},"type":"cta","assets":[],"variant":"default","schema_version":1},{"key":"81f4f54f-374a-5d33-9622-034b2b271376","data":{"items":[{"body":"Los conflictos laborales pueden generar importantes consecuencias económicas, operativas y reputacionales para una empresa. Si enfrentas una demanda o denuncia de un trabajador, recibirás asesoría y representación jurídica para evaluar los antecedentes, definir una estrategia y proteger los intereses de tu organización.","href":"/empresas/derecho-laboral","heading":"Derecho laboral","link_label":"Conocer el servicio"},{"body":"Una estructura jurídica sólida permite que tu empresa pueda crecer y tomar decisiones con mayor seguridad. Te asesoramos en la constitución de sociedades, modificaciones societarias, incorporación o salida de socios y otros actos relevantes para la organización de tu negocio.","href":"/empresas/derecho-corporativo-y-comercial","heading":"Derecho corporativo y comercial","link_label":"Conocer el servicio"},{"body":"Tu marca representa la identidad de tu empresa y puede convertirse en uno de sus activos más importantes. Te asesoramos durante el proceso de registro de marca ante INAPI, desde la revisión inicial hasta la obtención del registro, para que puedas proteger jurídicamente la identidad de tu negocio.","href":"/empresas/propiedad-intelectual","heading":"Propiedad intelectual","link_label":"Conocer el servicio"},{"body":"Participar en procesos de contratación con organismos públicos requiere comprender las bases, cumplir correctamente sus exigencias y actuar oportunamente frente a decisiones que puedan afectar a tu empresa.","href":"/empresas/contratacion-publica","heading":"Contratación pública","link_label":"Conocer el servicio"},{"body":"La mejor forma de enfrentar muchos conflictos legales es prevenirlos. Te asesoramos para identificar riesgos, fortalecer el cumplimiento normativo de tu empresa y adoptar medidas que permitan reducir contingencias, fiscalizaciones, sanciones y futuros conflictos.","href":"/empresas/asesoria-preventiva-empresarial","heading":"Asesoría preventiva empresarial","link_label":"Conocer el servicio"}],"heading":"Más áreas en las que podemos ayudarte"},"type":"card_grid","assets":[],"variant":"default","schema_version":1}],"authors":["d4d402d3-0f0b-5a3c-bf0c-93a5ee3ccfb1"],"excerpt":"Evalúa la situación financiera de tu empresa y los pasos que conviene analizar antes de actuar.","relations":[],"template_key":"default","cover_asset_id":"a8d56727-b8a4-4ea6-b7c5-345b6a0b7d5a","template_version":1}}],"samples":[{"author_name":"Ejemplo editable 1","quote":"Texto de ejemplo: el equipo nos explicó las alternativas con claridad y nos ayudó a comprender qué antecedentes debíamos reunir antes de tomar una decisión.","context":"Asesoría para personas · ejemplo"},{"author_name":"Ejemplo editable 2","quote":"Texto de ejemplo: valoramos la comunicación cercana y la explicación de los pasos del proceso. Pudimos plantear nuestras preguntas y entender el alcance de la asesoría.","context":"Acompañamiento jurídico · ejemplo"},{"author_name":"Ejemplo editable 3","quote":"Texto de ejemplo: recibimos una revisión ordenada de la situación de la empresa y una explicación de las opciones disponibles para definir los próximos pasos.","context":"Asesoría para empresas · ejemplo"}]}$payload$::jsonb;
 site uuid := '709bf171-8449-4177-a1f7-2facca7090a5';
 actor uuid := 'a9834185-147a-4f2c-9e6e-88dada938369';
 item jsonb; entry uuid; expected uuid; published uuid; latest uuid; revision uuid;
begin
 if not exists(select 1 from public.profiles where id=actor and is_admin and status='active') then raise exception 'Expected active administrator unavailable'; end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 perform 1 from public.sites where id=site for update;
 for item in select * from jsonb_array_elements(payload->'updates') loop
  entry:=(item->>'entry_id')::uuid;expected:=(item->>'expected_revision_id')::uuid;
  select published_revision_id into published from public.content_entries where id=entry and site_id=site and archived_at is null for update;
  if not found or published is distinct from expected then raise exception 'Published content changed: %',item->>'path'; end if;
  select id into latest from public.content_revisions where entry_id=entry order by revision_number desc limit 1;
  if latest is distinct from expected then raise exception 'Pending edits: %',item->>'path'; end if;
  if exists(select 1 from public.scheduled_publications where entry_id=entry and status='pending') then raise exception 'Scheduled publication: %',item->>'path'; end if;
  revision:=public.save_content_revision(entry,expected,item->'content');
  perform public.set_revision_state(revision,'approved');
  perform public.publish_content_revision(revision);
 end loop;
 for item in select value||jsonb_build_object('position',ordinality-1) from jsonb_array_elements(payload->'samples') with ordinality loop
  perform public.save_testimonial(site,null,null,item->>'author_name',item->>'quote',item->>'context',(item->>'position')::integer,false);
 end loop;
end;
$patch$;
select jsonb_build_object('revisions',(select jsonb_agg(jsonb_build_object('path',r.path,'revision_id',r.id,'revision_number',r.revision_number) order by r.path) from public.content_entries e join public.content_revisions r on r.id=e.published_revision_id where e.id=any(array['606582f3-942c-5755-9898-ce97e671154d','cea7ff50-d0ff-5c5c-abb3-05c7f2b529de','0431db74-5d6f-5f58-b9f5-4bc30de43baf','8b130478-5b90-5eb6-85b3-897d906317cc']::uuid[])), 'draft_examples',(select jsonb_agg(jsonb_build_object('id',id,'author_name',author_name,'is_published',is_published) order by position) from public.testimonials)) as result;
commit;
